from typing import List

class Solution:
    def minimumLengthEncoding(self, words: List[str]) -> int:
        good = set(words)
        for w in words:
            for i in range(1, len(w)):
                good.discard(w[i:])
        return sum(len(w) + 1 for w in good)

class Solution {
public:
    int minimumLengthEncoding(vector<string>& words) {
        unordered_set<string> good(words.begin(), words.end());
        for (const string& w : words) {
            for (size_t i = 1; i < w.length(); i++) {
                good.erase(w.substr(i));
            }
        }
        int ans = 0;
        for (const string& w : good) ans += w.length() + 1;
        return ans;
    }
};

class Solution {
    public int minimumLengthEncoding(String[] words) {
        Set<String> good = new HashSet<>(Arrays.asList(words));
        for (String w : words) {
            for (int i = 1; i < w.length(); i++) {
                good.remove(w.substring(i));
            }
        }
        int ans = 0;
        for (String w : good) ans += w.length() + 1;
        return ans;
    }
}

var minimumLengthEncoding = function(words) {
    const good = new Set(words);
    for (const w of words) {
        for (let i = 1; i < w.length; i++) {
            good.delete(w.slice(i));
        }
    }
    let ans = 0;
    for (const w of good) ans += w.length + 1;
    return ans;
};
